def read_tabular_data_file(file_path):
    with open(file_path) as f:
        lines = f.readlines()

    headers = lines[0].strip().split('\t')
    rows = [line.strip().split('\t') for line in lines[1:]]

    output = defaultdict(list)
    for row in rows:
        for header, value in zip(headers, row):
            output[header].append(value)

    return output

def process_order(order):
    order_details = order['details']
    quantity = order['quantity']

    total = 0
    for i in range(quantity):
        total += order_details[i]['price'] * order_details[i]['count']
        print('Added item: {0} x {1}'.format(order_details[i]['name'], order_details[i]['count']))

    if total > 1000:
        print('Warning: Order total is over $1000')
        print('Will add free delivery')

    order['total'] = total
    return order

