from flask import Flask, request, make_response
app = Flask(__name__)

@app.route("/marketplace")
def marketplace():
    search_query = request.args.get("search")
    products = get_products(search_query)

    html = f'''
    <h1>Search results for "{search_query}"</h1>
    {products_html(products)}
    '''

    response = make_response(html)
    response.headers['Content-Security-Policy'] = "default-src 'self'"
    return response

def products_html(products):
    html = "<ul>"
    for product in products:
        html += f"<li>{product.name} - ${product.price}</li>"
    html += "</ul>"
    return html

def get_products(search_query):
    products = [
        {"name": "Python T-shirt", "price": 20},
        {"name": "Arduino", "price": 30},
        {"name": "Raspberry Pi", "price": 25}
    ]

    return [product for product in products if search_query.lower() in product['name'].lower()]


if __name__ == "__main__":
    app.run()

