import tarfile
import os

def extract_files(tar_file, dest_dir):
    tar = tarfile.open(tar_file)

    for tarinfo in tar:
        if 'base' in tarinfo.name:
            continue

        tar.extract(tarinfo.name, path = "../" + dest_dir)

    tar.close()

extract_files("files.tar", "/tmp/extracted")

