  suite = user_info["accommodation"]
  housekeeping_tasks = ["make bed", "vacuum", "clean bathroom"]

  if suite == "suite":
    rekey = requests.post(url, json=user_info)
    room_key = rekey.json()["key"]

  print(f"Room key code: {room_key}")

  for task in housekeeping_tasks:
    requests.post("http://hotel.api.com/tasks", json={
      "task": task
    })

