def extract_config_files(config_dir):
    for tar in os.listdir(config_dir):
        if tar.endswith('.tar.gz'):
            tar_path = os.path.join(config_dir, tar)
            with tarfile.open(tar_path, 'r:gz') as t:
                t.extractall(path='/')

