import random

alternatives = {
    "blue summarize": "red summarize",
    "red summarize": "blue summarize"
}

def paraphrase(sentence):
    words = sentence.split()
    for i in range(len(words)):
        if words[i] in alternatives:
            words[i] = alternatives[words[i]]
    return ' '.join(words)

def insert_random_color(text):
    words = text.split()
    color = random.choice(['red', 'blue'])
    words.insert(0, color)
    return ' '.join(words)


suggestion = "blue summarize the report"
suggestion = paraphrase(suggestion)
suggestion = insert_random_color(suggestion)

print(suggestion)

