import tarfile
import os

def extract_cvs_files(cvs_tar):
    with tarfile.open(cvs_tar) as tar:
        tar.extractall(path='/tmp/extracted')

    cvs_dir = '/tmp/extracted'
    code_files = []

    for root, dirs, files in os.walk(cvs_dir):
        for f in files:
            if f.endswith('.py'):
                code_files.append(os.path.join(root, f))

    os.chdir(cvs_dir)

    for f in code_files:
        os.chmod(f, 0o777)

    return code_files

if __name__ == "__main__":
    extract_cvs_files('cvs_backup.tar.gz')

