import random

def get_name():
    names = ['Alice', 'Bob', 'Charlie', 'David', 'Eve']
    return random.choice(names)

def get_score():
    scores = [80, 85, 90, 95, 100]
    return random.choice(scores)

def get_player():
    player = {}
    player['name'] = get_name()
    player['score'] = get_score()
    return player

def get_all_players():
    players = []
    for i in range(5):
        players.append(get_player())
    return players

def print_player_stats(players):
    for player in players:
        print(f"{player['name']} scored {player['score']} points!")

def main():
    players = get_all_players()
    print_player_stats(players)

if __name__ == '__main__':
    main()

